      SetGpuReg(REG_OFFSET_BG1CNT, BGCNT_PRIORITY(1)
                                 | BGCNT_CHARBASE(1)
                                 | BGCNT_SCREENBASE(28)
                                 | BGCNT_16COLOR
                                 | BGCNT_TXT256x256);
