      LZDecompressVram(gIntroClouds_Gfx, VRAM);
      LZDecompressVram(gIntroClouds_Gfx, (BG_CHAR_ADDR(1)));
      LZDecompressVram(gIntroCloudsSun_Tilemap, (BG_SCREEN_ADDR(28)));
