/** static void Task_Scene3_Clouds(u8 taskId) */
export function Task_Scene3_Clouds(taskId: any): any {
  let data: any = gTasks[taskId].data;

       
      SetGpuReg(REG_OFFSET_BG0HOFS, (tCloudPos >> 8));
      SetGpuReg(REG_OFFSET_BG1HOFS, -(tCloudPos >> 8));

      switch (tState)
      {
      case 0:
           
           
          if (--tCloudPos == 0)
          {
               
              BeginNormalPaletteFade(PALETTES_ALL & ~1, 0, 16, 0, RGB_WHITEALPHA);
              tCloudPos = 80 << 8;
              tState++;
          }
          break;
      case 1:
           
          if (tCloudPos == 40 << 8)
              BeginNormalPaletteFade(PALETTES_BG & ~1, 3, 0, 16, RGB(9, 10, 10));

           
          if (tCloudPos != 0)
              tCloudPos -= 128;
          else if (!gPaletteFade.active)
              gTasks[taskId].func = Task_Scene3_LoadLightning;
          break;
      }
}

/** static void Task_Scene3_LoadLightning(u8 taskId) */
export function Task_Scene3_LoadLightning(taskId: any): any {
  LZDecompressVram(gIntroRayquaza_Tilemap, (BG_SCREEN_ADDR(28)));
      LZDecompressVram(gIntroRayquazaClouds_Tilemap, (BG_CHAR_ADDR(3)));
      LZDecompressVram(gIntroRayquaza_Gfx, (BG_CHAR_ADDR(1)));
      LZDecompressVram(gIntroRayquazaClouds_Gfx, VRAM);
      SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0
                                  | DISPCNT_OBJ_1D_MAP
                                  | DISPCNT_BG0_ON
                                  | DISPCNT_BG2_ON
                                  | DISPCNT_OBJ_ON
                                  | DISPCNT_WIN0_ON);
      gTasks[taskId].func = Task_Scene3_Lightning;
      gTasks[taskId].tState = 0;
      gTasks[taskId].tDelay = 1;
      gTasks[taskId].tTimer = 0;
      LoadCompressedSpriteSheetUsingHeap(sSpriteSheet_Lightning);
      LoadSpritePalettes(sSpritePalette_Lightning);
}

/** static void Task_Scene3_Lightning(u8 taskId) */
export function Task_Scene3_Lightning(taskId: any): any {
  let data: any = gTasks[taskId].data;
      let spriteId: any = null;

      switch (tState)
      {
      case 0:
          if (--tDelay == 0)
          {
               
              CreateSprite(sSpriteTemplate_Lightning, 200, 48, 0);
              spriteId = CreateSprite(sSpriteTemplate_Lightning, 200, 80, 1);
              StartSpriteAnim(gSprites[spriteId], 1);
              spriteId = CreateSprite(sSpriteTemplate_Lightning, 200, 112, 2);
              StartSpriteAnim(gSprites[spriteId], 2);
              tState++;
              tDelay = 72;
          }
          break;
      case 1:
          if (--tDelay == 0)
          {
               
              CreateSprite(sSpriteTemplate_Lightning, 40, 48, 0);
              spriteId = CreateSprite(sSpriteTemplate_Lightning, 40, 80, 1);
              StartSpriteAnim(gSprites[spriteId], 1);
              spriteId = CreateSprite(sSpriteTemplate_Lightning, 40, 112, 2);
              StartSpriteAnim(gSprites[spriteId], 2);
              tState++;
              tDelay = 48;
          }
          break;
      case 2:
          if (--tDelay == 0)
              gTasks[taskId].func = Task_Scene3_LoadRayquazaAttack;
          break;
      }
}

/** static void SpriteCB_Lightning(struct Sprite *sprite) */
export function SpriteCB_Lightning(sprite: any): any {
  if (sprite.animEnded)
          sprite.invisible = TRUE;

      switch(sprite.sState)
      {
      case 0:
          sprite.sPalIdx = 0x1C2;
          sprite.sState++;
      case 1:
          CpuCopy16(INTRO3_RAW_PTR(sprite.sPalIdx),gPlttBufferFaded[BG_PLTT_ID(5) + 13], PLTT_SIZEOF(1));
          sprite.sPalIdx += 2;
          if (sprite.sPalIdx != 0x1CE)
              break;
          sprite.sPalIdx = 0x1CC;
          sprite.sDelay = 4;
          sprite.sState++;
      case 2:
          if (--sprite.sDelay == 0)
          {
              sprite.sDelay = 4;
              CpuCopy16(INTRO3_RAW_PTR(sprite.sPalIdx),gPlttBufferFaded[BG_PLTT_ID(5) + 13], PLTT_SIZEOF(1));
              sprite.sPalIdx -= 2;
              if (sprite.sPalIdx == 0x1C0)
                  DestroySprite(sprite);
          }
          break;
      }
}

/** static void Task_Scene3_LoadRayquazaAttack(u8 taskId) */
export function Task_Scene3_LoadRayquazaAttack(taskId: any): any {
  let attackTaskId: any = null;

      LoadCompressedSpriteSheet(sSpriteSheet_RayquazaOrb);
      LoadSpritePalettes(sSpritePalette_RayquazaOrb);
      SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0
                                  | DISPCNT_OBJ_1D_MAP
                                  | DISPCNT_BG0_ON
                                  | DISPCNT_BG2_ON
                                  | DISPCNT_OBJ_ON
                                  | DISPCNT_WIN0_ON);
      gTasks[taskId].func = Task_Scene3_Rayquaza;
      BeginNormalPaletteFade(PALETTES_BG & ~(_0x21), 0, 16, 0, RGB(9, 10, 10));
      gTasks[taskId].tState = 0;
      gTasks[taskId].data[1] = 0xA8;
      gTasks[taskId].data[2] = -_0x10;
      gTasks[taskId].data[3] = -_0x88;
      gTasks[taskId].data[4] = -_0x10;
      attackTaskId = CreateTask(Task_RayquazaAttack, 0);
      gTasks[attackTaskId].tRayquazaTaskId = taskId;
}

/** static void Task_Scene3_Rayquaza(u8 taskId) */
export function Task_Scene3_Rayquaza(taskId: any): any {
  let data: any = gTasks[taskId].data;

      if (tTimer % 2 == 0)
          data[6] ^= 2;

      tTimer++;

      switch(tState)
      {
      case 0:
          if ((tTimer & 1) != 0)
          {
              data[1] -= 2;
              data[2]++;
              data[3] += 2;
              data[4]++;
          }
          if (data[1] == _0x68)
          {
              tState++;
              data[5] = 1;
          }
          break;
      case 1:
          tState++;
          data[5] = 4;
          break;
      case 2:
          data[1] += 4;
          data[2] -= 2;
          data[3] -= 4;
          data[4] -= 2;
          if (!gPaletteFade.active)
          {
              data[5] = 0x8C;
              tState++;
          }
          break;
      case 3:
          if (--data[5] == 0)
              gTasks[taskId].func = Task_EndIntroMovie;
          break;
      }
}

/** static void Task_EndIntroMovie(u8 taskId) */
export function Task_EndIntroMovie(taskId: any): any {
  DestroyTask(taskId);
      SetMainCallback2(MainCB2_EndIntro);
}

/** static void Task_RayquazaAttack(u8 taskId) */
export function Task_RayquazaAttack(taskId: any): any {
  let spriteId: any = null;
      let data: any = gTasks[taskId].data;
      data[2]++;

      switch(tState)
      {
      case 0:
          if ((data[2] & 1) != 0)
          {
              CpuCopy16(INTRO3_RAW_PTR(0x1A2 + data[1] * 2),gPlttBufferFaded[BG_PLTT_ID(5) + 14], PLTT_SIZEOF(1));
              data[1]++;
          }
          if (data[1] == 6)
          {
              tState++;
              data[1] = 0;
              data[3] = 10;
          }
          break;
      case 1:
          if (data[3] == 0)
          {
              if ((data[2] & 1) != 0)
              {
                  CpuCopy16(INTRO3_RAW_PTR(0x1A2 + data[1] * 2),gPlttBufferFaded[BG_PLTT_ID(5) + 8], PLTT_SIZEOF(1));
                  data[1]++;
              }
              if (data[1] == 6)
              {
                  tState++;
                  data[3] = 10;
              }
          }
          else
          {
              data[3]--;
          }
          break;
      case 2:
          if (data[3] == 0)
          {
              if ((data[2] & 1) != 0)
              {
                  CpuCopy16(INTRO3_RAW_PTR(_0x182 + data[1] * 2),gPlttBufferFaded[BG_PLTT_ID(5) + 12], PLTT_SIZEOF(1));
                  data[1]++;
              }
              if (data[1] == 6)
              {
                  spriteId = CreateSprite(sSpriteTemplate_RayquazaOrb, 120, 88, 15);
                  PlaySE(SE_INTRO_BLAST);
                  gSprites[spriteId].invisible = TRUE;
                  gSprites[spriteId].data[3] = tRayquazaTaskId;
                  tState++;
                  data[3] = 16;
              }
          }
          else
          {
              data[3]--;
          }
          break;
      case 3:
          if ((data[2] & 1) != 0)
          {
              if (--data[3] != 0)
              {
                  BlendPalette(BG_PLTT_ID(5), 16, data[3], RGB(9, 10, 10));
                  CpuCopy16(INTRO3_RAW_PTR(428),gPlttBufferFaded[BG_PLTT_ID(5) + 14], PLTT_SIZEOF(1));
                  CpuCopy16(INTRO3_RAW_PTR(428),gPlttBufferFaded[BG_PLTT_ID(5) + 8], PLTT_SIZEOF(1));
                  CpuCopy16(INTRO3_RAW_PTR(396),gPlttBufferFaded[BG_PLTT_ID(5) + 12], PLTT_SIZEOF(1));
              }
              else
              {
                  tState++;
                  data[3] = 53;
              }
          }
          break;
      case 4:
          if (--data[3] == 0)
          {
              BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_WHITE);
              tState++;
          }
          break;
      case 5:
          if (!gPaletteFade.active)
              DestroyTask(taskId);
          break;
      }
}

/** static void IntroResetGpuRegs(void) */
export function IntroResetGpuRegs(): any {
  SetGpuReg(REG_OFFSET_DISPCNT, 0);
      SetGpuReg(REG_OFFSET_BG3HOFS, 0);
      SetGpuReg(REG_OFFSET_BG3VOFS, 0);
      SetGpuReg(REG_OFFSET_BG2HOFS, 0);
      SetGpuReg(REG_OFFSET_BG2VOFS, 0);
      SetGpuReg(REG_OFFSET_BG1HOFS, 0);
      SetGpuReg(REG_OFFSET_BG1VOFS, 0);
      SetGpuReg(REG_OFFSET_BG0HOFS, 0);
      SetGpuReg(REG_OFFSET_BG0VOFS, 0);
      SetGpuReg(REG_OFFSET_BLDCNT, 0);
      SetGpuReg(REG_OFFSET_BLDALPHA, 0);
      SetGpuReg(REG_OFFSET_BLDY, 0);
}

/** static void Task_BlendLogoIn(u8 taskId) */
export function Task_BlendLogoIn(taskId: any): any {
  switch (gTasks[taskId].tState)
      {
      case 0:
      default:
          SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_BLEND
                                     | BLDCNT_TGT2_BG0
                                     | BLDCNT_TGT2_BG1
                                     | BLDCNT_TGT2_BG2
                                     | BLDCNT_TGT2_BG3
                                     | BLDCNT_TGT2_OBJ
                                     | BLDCNT_TGT2_BD);
          SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[31]);
          SetGpuReg(REG_OFFSET_BLDY, 0);
          gTasks[taskId].data[1] = ARRAY_COUNT(gTitleScreenAlphaBlend);
          gTasks[taskId].tState++;
          break;
      case 1:
          if (gTasks[taskId].data[1] != 0)
          {
              let tmp: any = null;

              gTasks[taskId].data[1]--;
              tmp = gTasks[taskId].data[1] / 2;
              SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[tmp]);
          }
          else
          {
              SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[0]);
              gTasks[taskId].data[1] = ARRAY_COUNT(gTitleScreenAlphaBlend) / 4;
              gTasks[taskId].tState++;
          }
          break;
      case 2:
          SetGpuReg(REG_OFFSET_BLDCNT, 0);
          SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          SetGpuReg(REG_OFFSET_BLDY, 0);
          DestroyTask(taskId);
          break;
      }
}

/** static void Task_BlendLogoOut(u8 taskId) */
export function Task_BlendLogoOut(taskId: any): any {
  switch (gTasks[taskId].tState)
      {
      case 0:
      default:
          SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_BLEND
                                     | BLDCNT_TGT2_BG0
                                     | BLDCNT_TGT2_BG1
                                     | BLDCNT_TGT2_BG2
                                     | BLDCNT_TGT2_BG3
                                     | BLDCNT_TGT2_OBJ
                                     | BLDCNT_TGT2_BD);
          SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[0]);
          SetGpuReg(REG_OFFSET_BLDY, 0);
          gTasks[taskId].data[1] = 0;
          gTasks[taskId].tState++;
          break;
      case 1:
          if (gTasks[taskId].data[1] < ARRAY_COUNT(gTitleScreenAlphaBlend) - 2)
          {
              let tmp: any = null;

              gTasks[taskId].data[1]++;
              tmp = gTasks[taskId].data[1] / 2;
              SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[tmp]);
          }
          else
          {
              SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[31]);
              gTasks[taskId].data[1] = ARRAY_COUNT(gTitleScreenAlphaBlend) / 4;
              gTasks[taskId].tState++;
          }
          break;
      case 2:
          if (gTasks[taskId].data[1] != 0)
          {
              gTasks[taskId].data[1]--;
          }
          else
          {
              SetGpuReg(REG_OFFSET_BLDCNT, 0);
              SetGpuReg(REG_OFFSET_BLDALPHA, 0);
              SetGpuReg(REG_OFFSET_BLDY, 0);
              DestroyTask(taskId);
          }
          break;
      }
}

/** void PanFadeAndZoomScreen(u16 screenX, u16 screenY, u16 zoom, u16 alpha) */
export function PanFadeAndZoomScreen(screenX: any, screenY: any, zoom: any, alpha: any): any {
  let src: any = null;
      let dest: any = null;

      src.texX = _0x8000;
      src.texY = _0x8000;
      src.scrX = screenX;
      src.scrY = screenY;
      src.sx = zoom;
      src.sy = zoom;
      src.alpha = alpha;
      BgAffineSet(src,dest, 1);
      SetGpuReg(REG_OFFSET_BG2PA, dest.pa);
      SetGpuReg(REG_OFFSET_BG2PB, dest.pb);
      SetGpuReg(REG_OFFSET_BG2PC, dest.pc);
      SetGpuReg(REG_OFFSET_BG2PD, dest.pd);
      SetGpuReg(REG_OFFSET_BG2X_L, dest.dx);
      SetGpuReg(REG_OFFSET_BG2X_H, dest.dx >> 16);
      SetGpuReg(REG_OFFSET_BG2Y_L, dest.dy);
      SetGpuReg(REG_OFFSET_BG2Y_H, dest.dy >> 16);
}

/** static void SpriteCB_WaterDrop_Ripple(struct Sprite *sprite) */
export function SpriteCB_WaterDrop_Ripple(sprite: any): any {
  let palNum: any = null;

      if (sprite.data[2] >= 192)
      {
          if (sprite.data[3] != 0)
          {
              sprite.data[3]--;
          }
          else
          {
              sprite.invisible = FALSE;
              SetOamMatrix(sprite.data[1], sprite.data[2], 0, 0, sprite.data[2]);
              sprite.data[2] = (sprite.data[2] * 95) / 100;
              palNum = (sprite.data[2] - 192) / 128 + 9;
              if (palNum > 15)
                  palNum = 15;
              sprite.oam.paletteNum = palNum;
          }
      }
      else
      {
          DestroySprite(sprite);
      }
}

/** static void SpriteCB_WaterDropHalf(struct Sprite *sprite) */
export function SpriteCB_WaterDropHalf(sprite: any): any {
  if (gSprites[sprite.data[7]].data[7] != 0)
      {
          sprite.invisible = TRUE;
          sprite.x += sprite.x2;
          sprite.y += sprite.y2;
          StartSpriteAnim(sprite, DROP_ANIM_RIPPLE);
          sprite.data[2] = 1024;
          sprite.data[3] = 8 * (sprite.data[1] & 3);
          sprite.callback = SpriteCB_WaterDrop_Ripple;
          sprite.oam.shape = SPRITE_SHAPE(_64x32);
          sprite.oam.size = SPRITE_SIZE(_64x32);
          CalcCenterToCornerVec(sprite, SPRITE_SHAPE(_64x32), SPRITE_SIZE(_64x32), ST_OAM_AFFINE_ERASE);
      }
      else
      {
          sprite.x2 = gSprites[sprite.data[7]].x2;
          sprite.y2 = gSprites[sprite.data[7]].y2;
          sprite.x = gSprites[sprite.data[7]].x;
          sprite.y = gSprites[sprite.data[7]].y;
      }
}

/** static void SpriteCB_WaterDrop(struct Sprite *sprite) */
export function SpriteCB_WaterDrop(sprite: any): any {
  if (sprite.sState != 0)
          sprite.callback = SpriteCB_WaterDrop_Slide;
}

/** static void SpriteCB_WaterDrop_Slide(struct Sprite *sprite) */
export function SpriteCB_WaterDrop_Slide(sprite: any): any {
  if (sprite.x <= 116)
      {
          sprite.y += sprite.y2;
          sprite.y2 = 0;
          sprite.x += 4;
          sprite.x2 = -4;
          sprite.data[4] = 128;
          sprite.callback = SpriteCB_WaterDrop_ReachLeafEnd;
      }
      else
      {
          let data2: any = null;
          let data3: any = null;
          let data4: any = null;
          let sin1: any = null;
          let sin2: any = null;
          let sin3: any = null;
          let sin4: any = null;
          let var1: any = null;
          let var2: any = null;
          let var3: any = null;
          let var4: any = null;
          let temp: any = null;

          data4 = sprite.data[4];
          sin1 = gSineTable[data4];
          sin2 = gSineTable[(data4 + 64)];
          sprite.data[4] += 2;
          sprite.y2 = sin1 / 32;
          sprite.x--;
          if (sprite.x & 1)
              sprite.y++;
          temp = -sin2 / 16;
          data2 = sprite.data[2];
          data3 = sprite.data[3];
          sin3 = gSineTable[(temp - 16)];
          sin4 = gSineTable[(temp + 48)];
          var1 = sin4 * data2 / 256;
          var2 = -sin3 * data3 / 256;
          var3 = sin3 * data2 / 256;
          var4 = sin4 * data3 / 256;
          SetOamMatrix(sprite.data[1], data2, 0, 0, data3);
          SetOamMatrix(sprite.data[1] + 1, var1, var3, var2, var4);
          SetOamMatrix(sprite.data[1] + 2, var1, var3, var2 * 2, var4 * 2);
      }
}

/** static void SpriteCB_WaterDrop_ReachLeafEnd(struct Sprite *sprite) */
export function SpriteCB_WaterDrop_ReachLeafEnd(sprite: any): any {
  SetOamMatrix(sprite.data[1], sprite.data[6] + 64, 0, 0, sprite.data[6] + 64);
      SetOamMatrix(sprite.data[1] + 1, sprite.data[6] + 64, 0, 0, sprite.data[6] + 64);
      SetOamMatrix(sprite.data[1] + 2, sprite.data[6] + 64, 0, 0, sprite.data[6] + 64);
      if (sprite.data[4] != MAX_SPRITES)
      {
          let sinIdx: any = null;
          sprite.data[4] -= 8;
          sinIdx = sprite.data[4];
          sprite.x2 = gSineTable[(sinIdx + 64)] / 64;
          sprite.y2 = gSineTable[sinIdx] / 64;
      }
      else
      {
          sprite.data[4] = 0;
          sprite.callback = SpriteCB_WaterDrop_DangleFromLeaf;
      }
}

/** static void SpriteCB_WaterDrop_DangleFromLeaf(struct Sprite *sprite) */
export function SpriteCB_WaterDrop_DangleFromLeaf(sprite: any): any {
  if (sprite.data[0] != 2)
      {
          let r2: any = null;

          sprite.data[4] += 8;
          r2 = gSineTable[sprite.data[4]] / 16 + 64;
          sprite.x2 = gSineTable[(r2 + 64)] / 64;
          sprite.y2 = gSineTable[r2] / 64;
      }
      else
      {
          sprite.callback = SpriteCB_WaterDrop_Fall;
      }
}

/** static void SpriteCB_WaterDrop_Fall(struct Sprite *sprite) */
export function SpriteCB_WaterDrop_Fall(sprite: any): any {
  if (sprite.y < sprite.data[5])
      {
          sprite.y += 4;
      }
      else
      {
          sprite.data[7] = 1;
          sprite.invisible = TRUE;
          sprite.x += sprite.x2;
          sprite.y += sprite.y2;
          StartSpriteAnim(sprite, DROP_ANIM_RIPPLE);
          sprite.data[2] = 1024;
          sprite.data[3] = 8 * (sprite.data[1] & 3);
          sprite.callback = SpriteCB_WaterDrop_Ripple;
          sprite.oam.shape = SPRITE_SHAPE(_64x32);
          sprite.oam.size = SPRITE_SIZE(_64x32);
          CalcCenterToCornerVec(sprite, SPRITE_SHAPE(_64x32), SPRITE_SIZE(_64x32), ST_OAM_AFFINE_ERASE);
      }
}

/** static void SpriteCB_WaterDropShort(struct Sprite *sprite) */
export function SpriteCB_WaterDropShort(sprite: any): any {
  if (sprite.y < sprite.data[5])
      {
          sprite.y += 4;
      }
      else
      {
          sprite.data[7] = 1;
          sprite.invisible = TRUE;
          sprite.x += sprite.x2;
          sprite.y += sprite.y2;
          StartSpriteAnim(sprite, DROP_ANIM_RIPPLE);
          sprite.data[2] = 1024;
          sprite.data[3] = 8 * (sprite.data[1] & 3);
          sprite.callback = SpriteCB_WaterDrop_Ripple;
          sprite.oam.shape = SPRITE_SHAPE(_64x32);
          sprite.oam.size = SPRITE_SIZE(_64x32);
          CalcCenterToCornerVec(sprite, SPRITE_SHAPE(_64x32), SPRITE_SIZE(_64x32), ST_OAM_AFFINE_ERASE);
      }
}

/** static u8 CreateWaterDrop(s16 x, s16 y, u16 c, u16 d, u16 e, u8 fallImmediately) */
export function CreateWaterDrop(x: any, y: any, c: any, d: any, e: any, fallImmediately: any): any {
  let spriteId: any = null;
      let oldSpriteId: any = null;

       
      spriteId = CreateSprite(sSpriteTemplate_WaterDrop, x, y, 1);
      gSprites[spriteId].data[0] = 0;
      gSprites[spriteId].data[7] = 0;
      gSprites[spriteId].data[1] = d;
      gSprites[spriteId].data[2] = c;
      gSprites[spriteId].data[3] = c;
      gSprites[spriteId].data[5] = e;
      gSprites[spriteId].data[6] = c;
      gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_DOUBLE;
      gSprites[spriteId].oam.matrixNum = d;
      CalcCenterToCornerVec(gSprites[spriteId], SPRITE_SHAPE(_32x32), SPRITE_SIZE(_32x32), ST_OAM_AFFINE_ERASE);
      StartSpriteAnim(gSprites[spriteId], DROP_ANIM_REFLECTION);
      if (!fallImmediately)
          gSprites[spriteId].callback = SpriteCB_WaterDrop;  
      else
          gSprites[spriteId].callback = SpriteCB_WaterDropShort;  
      oldSpriteId = spriteId;

       
       
      spriteId = CreateSprite(sSpriteTemplate_WaterDrop, x, y, 1);
      gSprites[spriteId].data[7] = oldSpriteId;
      gSprites[spriteId].data[1] = d + 1;
      gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_DOUBLE;
      gSprites[spriteId].oam.matrixNum = d + 1;
      CalcCenterToCornerVec(gSprites[spriteId], SPRITE_SHAPE(_32x32), SPRITE_SIZE(_32x32), ST_OAM_AFFINE_ERASE);
      gSprites[spriteId].callback = SpriteCB_WaterDropHalf;

       
      spriteId = CreateSprite(sSpriteTemplate_WaterDrop, x, y, 1);
      gSprites[spriteId].data[7] = oldSpriteId;
      gSprites[spriteId].data[1] = d + 2;
      StartSpriteAnim(gSprites[spriteId], DROP_ANIM_LOWER_HALF);
      gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_DOUBLE;
      gSprites[spriteId].oam.matrixNum = d + 2;
      CalcCenterToCornerVec(gSprites[spriteId], SPRITE_SHAPE(_32x32), SPRITE_SIZE(_32x32), ST_OAM_AFFINE_ERASE);
      gSprites[spriteId].callback = SpriteCB_WaterDropHalf;

      SetOamMatrix(d, c + 32, 0, 0, c + 32);
      SetOamMatrix(d + 1, c + 32, 0, 0, c + 32);
      SetOamMatrix(d + 2, c + 32, 0, 0, 2 * (c + 32));

      return oldSpriteId;
}

/** static void SpriteCB_PlayerOnBicycle(struct Sprite *sprite) */
export function SpriteCB_PlayerOnBicycle(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
           
          StartSpriteAnimIfDifferent(sprite, 0);
          sprite.x--;
          break;
      case 1:
           
          StartSpriteAnimIfDifferent(sprite, 0);
          if (gIntroFrameCounter & 7)
              return;
          sprite.x++;
          break;
      case 2:
           
          if (sprite.x <= 120 || gIntroFrameCounter & 7)
              sprite.x++;
          break;
      case 3:
           
          break;
      case 4:
           
          if (sprite.x > -32)
              sprite.x -= 2;
          break;
      }

      if (gIntroFrameCounter & 7)
          return;

       
      if (sprite.y2 != 0)
      {
           
          sprite.y2 = 0;
      }
      else
      {
           
          switch (Random() & 3)
          {
          case 0:
              sprite.y2 = -1;
              break;
          case 1:
              sprite.y2 = 1;
              break;
          case 2:
          case 3:
              sprite.y2 = 0;
              break;
          }
      }
}

/** static void SpriteCB_Flygon(struct Sprite *sprite) */
export function SpriteCB_Flygon(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
          break;
      case 1:
          if (sprite.x2 + sprite.x < DISPLAY_WIDTH + 64)
              sprite.x2 += 8;
          else
              sprite.sState = 2;
          break;
      case 2:
          if (sprite.x2 + sprite.x > 120)
              sprite.x2 -= 1;
          else
              sprite.sState = 3;
          break;
      case 3:
          if (sprite.x2 > 0)
              sprite.x2 -= 2;
          break;
      }
      sprite.y2 = Sin(sprite.sSinIdx, 8) - sFlygonYOffset;
      sprite.sSinIdx += 4;
}

/** static void SpriteCB_LogoLetter(struct Sprite *sprite) */
export function SpriteCB_LogoLetter(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
          if (sprite.sTimer != 0)
          {
              sprite.sTimer--;
          }
          else
          {
               
              sprite.invisible = FALSE;
              StartSpriteAffineAnim(sprite, 1);
              sprite.sState++;
          }
          break;
      case 1:
          if (gIntroFrameCounter == TIMER_LOGO_LETTERS_COLOR)
          {
               
              sprite.sState++;
              sprite.sTimer = COLOR_CHANGES;
              sprite.sColorDelay = 2;
          }
          break;
      case 2:
           
          if (sprite.sColorDelay == 0)
          {
              sprite.sColorDelay = 2;
              if (sprite.sTimer != 0)
              {
                  CpuCopy16(gIntroGameFreakTextFade_Pal[sprite.sTimer],gPlttBufferFaded[OBJ_PLTT_ID(1) + 15], PLTT_SIZEOF(1));
                  CpuCopy16(gIntroGameFreakTextFade_Pal[sprite.sTimer + 16],gPlttBufferFaded[OBJ_PLTT_ID(1) + 4], PLTT_SIZEOF(1));
                  CpuCopy16(gIntroGameFreakTextFade_Pal[sprite.sTimer + 32],gPlttBufferFaded[OBJ_PLTT_ID(1) + 10], PLTT_SIZEOF(1));
                  sprite.sTimer--;
              }
              else
              {
                  CpuCopy16(gIntroGameFreakTextFade_Pal[sprite.sTimer],gPlttBufferFaded[OBJ_PLTT_ID(1) + 15], PLTT_SIZEOF(1));
                  CpuCopy16(gIntroGameFreakTextFade_Pal[sprite.sTimer + 16],gPlttBufferFaded[OBJ_PLTT_ID(1) + 4], PLTT_SIZEOF(1));
                  CpuCopy16(gIntroGameFreakTextFade_Pal[sprite.sTimer + 32],gPlttBufferFaded[OBJ_PLTT_ID(1) + 10], PLTT_SIZEOF(1));
                  sprite.sState++;
              }
          }
          else
          {
              sprite.sColorDelay--;
          }
          break;
      case 3:
           
          if (sprite.sColorDelay != 0)
          {
              sprite.sColorDelay--;
          }
          else
          {
              sprite.sColorDelay = 2;
              if (sprite.sTimer <= COLOR_CHANGES)
              {
                  CpuCopy16(gIntroGameFreakTextFade_Pal[sprite.sTimer],gPlttBufferFaded[OBJ_PLTT_ID(1) + 15], PLTT_SIZEOF(1));
                  CpuCopy16(gIntroGameFreakTextFade_Pal[sprite.sTimer + 16],gPlttBufferFaded[OBJ_PLTT_ID(1) + 4], PLTT_SIZEOF(1));
                  CpuCopy16(gIntroGameFreakTextFade_Pal[sprite.sTimer + 32],gPlttBufferFaded[OBJ_PLTT_ID(1) + 10], PLTT_SIZEOF(1));
                  sprite.sTimer++;
              }
              else
              {
                  sprite.sState++;
              }
          }
          break;
      case 4:
          if (gIntroFrameCounter == TIMER_LOGO_DISAPPEAR)
          {
               
              StartSpriteAffineAnim(sprite, 2);
              sprite.oam.objMode = ST_OAM_OBJ_BLEND;
              sprite.sState++;
          }
          break;
      case 5:
           
          sprite.sLetterX += sGameFreakLettersMoveSpeed[sprite.sLetterId];
          sprite.x2 = (sprite.sLetterX & 0xFF00) >> 8;
          if (sprite.sLetterId < 4)
          {
               
              let temp: any = sprite.x2;
              sprite.x2 = -temp;
          }
          if (sprite.affineAnimEnded)
              DestroySprite(sprite);
          break;
      }
}

/** static void SpriteCB_GameFreakLogo(struct Sprite *sprite) */
export function SpriteCB_GameFreakLogo(sprite: any): any {
  switch(sprite.sState)
      {
      case 0:
          if (gIntroFrameCounter == TIMER_LOGO_APPEAR)
          {
              sprite.invisible = FALSE;
              sprite.sState++;
          }
          break;
      case 1:
          if (gIntroFrameCounter == TIMER_LOGO_DISAPPEAR)
          {
               
              StartSpriteAffineAnim(sprite, 3);
              sprite.sState++;
          }
          break;
      case 2:
          if (sprite.affineAnimEnded)
              DestroySprite(sprite);
          break;
      }
}

/** static u8 CreateGameFreakLogoSprites(s16 x, s16 y, s16 unused) */
export function CreateGameFreakLogoSprites(x: any, y: any, unused: any): any {
  let i: any = null;
      let spriteId: any = null;

       
      for (i = 0; i < NUM_GF_LETTERS; i++)
      {
          spriteId = CreateSprite(sSpriteTemplate_GameFreakLetter, sGameFreakLetterData[i][1] + x, y - 4, 0);
          gSprites[spriteId].sState = 0;
          gSprites[spriteId].sTimer = sGameFreakLetterStartDelays[i];
          gSprites[spriteId].sLetterId = i;
          gSprites[spriteId].invisible = TRUE;
          gSprites[spriteId].oam.matrixNum = i + 12;
          StartSpriteAnim(gSprites[spriteId], sGameFreakLetterData[i][0]);
          StartSpriteAffineAnim(gSprites[spriteId], 0);
      }

       
      spriteId = CreateSprite(sSpriteTemplate_GameFreakLogo, 120, y - 6, 0);
      gSprites[spriteId].sState = 0;
      gSprites[spriteId].invisible = TRUE;
      gSprites[spriteId].oam.matrixNum = i + 12;
      StartSpriteAffineAnim(gSprites[spriteId], 1);

      return spriteId;
}

/** static void SpriteCB_FlygonSilhouette(struct Sprite *sprite) */
export function SpriteCB_FlygonSilhouette(sprite: any): any {
  sprite.sTimer++;

      if (sprite.sState != 0)
      {
          let sin: any = null;
          let cos: any = null;

          let a, b, c, d;
           
          sin = gSineTable[sprite.sRot];
          cos = gSineTable[(sprite.sRot + 64)];
           
          d = Q_8_8_TO_INT( cos * sprite.sScale);
          c = Q_8_8_TO_INT(-sin * sprite.sScale);
          b = Q_8_8_TO_INT( sin * sprite.sScale);
          a = Q_8_8_TO_INT( cos * sprite.sScale);

          SetOamMatrix(1, a, b, c, d);
      }

      switch (sprite.sState)
      {
      case 0:
      default:
          sprite.oam.affineMode = ST_OAM_AFFINE_DOUBLE;
          sprite.oam.matrixNum = 1;
          CalcCenterToCornerVec(sprite, SPRITE_SHAPE(_64x32), SPRITE_SIZE(_64x32), ST_OAM_AFFINE_DOUBLE);
          sprite.invisible = FALSE;
          sprite.sState = 1;
          sprite.sScale = 128;
          sprite.sRot = 0;
          sprite.sPos = 0;
          break;
      case 1:
          sprite.x2 = -Sin(sprite.sPos, 140);
          sprite.y2 = -Sin(sprite.sPos, 120);
          sprite.sScale += 7;
          sprite.sPos += 3;
          if (sprite.x + sprite.x2 <= -16)
          {
              sprite.oam.priority = 3;
              sprite.sState++;
              sprite.x = 20;
              sprite.y = 40;
              sprite.sScale = 512;
              sprite.sRot = 0;
              sprite.sPos = 16;
          }
          break;
      case 2:
          sprite.x2 = Sin(sprite.sPos, 34);
          sprite.y2 = -Cos(sprite.sPos, 60);
          sprite.sScale += 2;
          if (sprite.sTimer % 5 == 0)
              sprite.sPos++;
          break;
      }
}

/** static void SpriteCB_RayquazaOrb(struct Sprite *sprite) */
export function SpriteCB_RayquazaOrb(sprite: any): any {
  let foo: any = null;
      switch (sprite.sState)
      {
      case 0:
      default:
          sprite.invisible = FALSE;
          sprite.oam.affineMode = ST_OAM_AFFINE_DOUBLE;
          sprite.oam.matrixNum = 18;
          CalcCenterToCornerVec(sprite, SPRITE_SHAPE(_64x64), SPRITE_SIZE(_64x64), ST_OAM_AFFINE_DOUBLE);
          sprite.data[1] = 0;
          sprite.sState = 1;
           
      case 1:
          sprite.data[7]++;
          if (sprite.data[7] & 1)
          {
              sprite.invisible = TRUE;
          }
          else
          {
              sprite.invisible = FALSE;
              if (sprite.data[1] < 64)
                  sprite.data[1]++;
          }
          foo = 256 - gSineTable[sprite.data[1]] / 2;
          SetOamMatrix(18, foo, 0, 0, foo);
          break;
      }
}

